The change enables connect to and reading Pulse rate and SpO2 % from a BerryMed Bluetooth LE enabled PulseOximeter device. It can be extended to support other bluetooth devices. 

Here is sample use of the class
#include "PulseOximeterService.h"

void setup() {
  Serial.begin(115200);
  Serial.println("Starting Pulse Oximeter BLE Client application...");
  esp_log_level_set("PulseOximeterService", ESP_LOG_VERBOSE);        // set all components to ERROR level
  PulseOximeterService::Instance().Start();
} // End of setup.


// This is the Arduino main loop function.
void loop() {

  PulseOximeterService::Instance().Tick();
  PulseOximeterReading reading = PulseOximeterService::Instance().GetReading();
  ESP_LOGE(LOG_TAG, "Timestamp : %ld IsValid : %d IsFingerPresent : %d Pulse : %d bpm Sp02 : %d %%", reading.Timestamp, reading.IsValid, reading.IsFingerPresent, reading.PulseRateBPM, reading.SpO2);
  delay(100); // Delay a second between loops.
} // End of loop

